INSERT INTO "interview" VALUES (32048,'Je promenais mon chien comme chaque soir et il s''est mis à tirer sur sa laisse en aboyant vers le fond de la rue. Sur le moment j''ai pensé à un chat. Avec le recul je me demande s''il n''avait pas entendu quelque chose, mais je ne vais pas bâtir une accusation sur l''humeur d''un teckel.'),
 (45107,'On m''a dit que quelqu''un du quartier avait « tout vu », mais quand je lui ai demandé, il m''a répondu qu''il ne se souvenait plus de rien. C''est un quartier tranquille d''habitude, ça nous a tous secoués. Ma femme était avec moi, elle vous dira la même chose.'),
 (96012,'Mon fils est rentré tard ce soir-là et m''a dit qu''il y avait beaucoup de police en bas de la rue. Je n''ai pas cherché à en savoir plus. Vous n''êtes pas le premier à me poser la question. Je peux vous donner le numéro de mon employeur si vous voulez vérifier. Je n''ai pas regardé l''heure, mais il ne faisait pas encore tout à fait nuit.'),
 (26383,'Je n''ai aucune idée de ce dont vous parlez. Je peux vous donner le numéro de mon employeur si vous voulez vérifier. Ma femme était avec moi, elle vous dira la même chose.'),
 (83110,'J''ai relevé une plaque d''immatriculation ce soir-là parce que la voiture était très mal garée. Je l''avais notée sur un bout de papier que j''ai perdu depuis. Franchement, je préfère ne pas m''avancer.'),
 (96351,'J''étais au restaurant avec des amis toute la soirée. Nous sommes arrivés vers dix-neuf heures et nous ne sommes repartis qu''à la fermeture. Le patron pourra le confirmer, il nous connaît bien : nous y allons presque toutes les semaines depuis des années. J''ai déjà tout raconté à votre collègue la semaine dernière.'),
 (52923,'Je n''ai pas mes lunettes sur moi, je ne peux rien affirmer de précis. C''est un quartier tranquille d''habitude, ça nous a tous secoués. Ne comptez pas sur moi pour témoigner au tribunal.'),
 (63853,'Il y avait une voiture sombre arrêtée un peu plus loin, moteur allumé. Ça m''a paru bizarre sur le moment, puis je n''y ai plus pensé. Tout ce que je sais, je l''ai lu dans le journal.'),
 (78863,'Il faisait déjà nuit, je n''ai pas vu grand-chose depuis mon balcon.'),
 (66010,'Je n''ai aucune idée de ce dont vous parlez. J''espère que vous le retrouverez rapidement. Si ça me revient, je vous appelle. Je peux vous donner le numéro de mon employeur si vous voulez vérifier.'),
 (72448,'J''étais au restaurant avec des amis toute la soirée. Nous sommes arrivés vers dix-neuf heures et nous ne sommes repartis qu''à la fermeture. Le patron pourra le confirmer, il nous connaît bien : nous y allons presque toutes les semaines depuis des années. Ma femme était avec moi, elle vous dira la même chose.'),
 (71364,'Je promenais mon chien deux rues plus loin, je n''ai rien vu. Je peux vous donner le numéro de mon employeur si vous voulez vérifier. Franchement, je préfère ne pas m''avancer.'),
 (47375,'J''ai cru entendre crier, mais c''était peut-être la télévision des voisins. Je peux vous donner le numéro de mon employeur si vous voulez vérifier.'),
 (87942,'Je ne veux pas être mêlé à cette histoire, j''ai déjà eu assez d''ennuis comme ça. Je n''ai pas regardé l''heure, mais il ne faisait pas encore tout à fait nuit. Ma femme était avec moi, elle vous dira la même chose.'),
 (57034,'J''étais au restaurant avec des amis toute la soirée. Nous sommes arrivés vers dix-neuf heures et nous ne sommes repartis qu''à la fermeture. Le patron pourra le confirmer, il nous connaît bien : nous y allons presque toutes les semaines depuis des années.'),
 (99744,'J''ai relevé une plaque d''immatriculation ce soir-là parce que la voiture était très mal garée. Je l''avais notée sur un bout de papier que j''ai perdu depuis. C''est un quartier tranquille d''habitude, ça nous a tous secoués. Ma femme était avec moi, elle vous dira la même chose. Franchement, je préfère ne pas m''avancer.'),
 (82750,'Je rentrais du travail et je n''ai croisé personne sur le trajet. J''ai déjà tout raconté à votre collègue la semaine dernière. Ne comptez pas sur moi pour témoigner au tribunal. C''est un quartier tranquille d''habitude, ça nous a tous secoués.'),
 (32554,'Tout m''a semblé parfaitement normal. J''ai déjà tout raconté à votre collègue la semaine dernière.'),
 (66291,'J''étais au restaurant avec des amis toute la soirée. Nous sommes arrivés vers dix-neuf heures et nous ne sommes repartis qu''à la fermeture. Le patron pourra le confirmer, il nous connaît bien : nous y allons presque toutes les semaines depuis des années. C''est un quartier tranquille d''habitude, ça nous a tous secoués.'),
 (15379,'Tout m''a semblé parfaitement normal. Je peux vous donner le numéro de mon employeur si vous voulez vérifier. J''ai déjà tout raconté à votre collègue la semaine dernière.'),
 (43662,'Je ne me souviens pas de la date exacte, désolé. Je peux vous donner le numéro de mon employeur si vous voulez vérifier.'),
 (44437,'J''habite juste en face et je passe mes soirées à ma fenêtre, c''est vrai. Mais ce soir-là j''étais chez ma fille pour son anniversaire. J''ai appris la nouvelle le lendemain matin par la boulangère, qui la tenait de son mari, qui l''avait entendue à la radio. Vous n''êtes pas le premier à me poser la question. Ne comptez pas sur moi pour témoigner au tribunal. Si ça me revient, je vous appelle.'),
 (30346,'J''ai témoigné dans une affaire il y a trois ans et ça m''a coûté des mois de tracas. Alors cette fois je vais être très clair : je n''étais pas là, je n''ai rien vu, je ne connais personne dans cette histoire et je n''ai aucune intention de me retrouver à nouveau convoqué tous les quinze jours. Vous devriez interroger les gens de l''immeuble d''en face, ils voient tout. Je ne connais personne qui aurait pu faire une chose pareille.'),
 (40717,'J''ai vu une voiture passer, mais je n''ai fait attention ni au modèle ni à la plaque. Ne comptez pas sur moi pour témoigner au tribunal. Je n''ai pas regardé l''heure, mais il ne faisait pas encore tout à fait nuit. Ma femme était avec moi, elle vous dira la même chose.'),
 (19894,'J''étais chez moi, je regardais la télévision.'),
 (56691,'J''attendais le bus, je n''ai rien vu de particulier. J''espère que vous le retrouverez rapidement. Je suis désolé de ne pas pouvoir vous aider davantage.'),
 (73391,'Je n''ai pas mes lunettes sur moi, je ne peux rien affirmer de précis. Franchement, je préfère ne pas m''avancer. Ma femme était avec moi, elle vous dira la même chose. J''espère que vous le retrouverez rapidement.'),
 (86248,'Je n''ai pas mes lunettes sur moi, je ne peux rien affirmer de précis. Tout ce que je sais, je l''ai lu dans le journal. C''est un quartier tranquille d''habitude, ça nous a tous secoués. Vous n''êtes pas le premier à me poser la question.'),
 (75814,'J''ai vu une voiture passer, mais je n''ai fait attention ni au modèle ni à la plaque. Je n''ai pas regardé l''heure, mais il ne faisait pas encore tout à fait nuit.'),
 (31856,'J''habite juste en face et je passe mes soirées à ma fenêtre, c''est vrai. Mais ce soir-là j''étais chez ma fille pour son anniversaire. J''ai appris la nouvelle le lendemain matin par la boulangère, qui la tenait de son mari, qui l''avait entendue à la radio.'),
 (65952,'J''étais chez moi, je regardais la télévision.'),
 (15859,'Je n''habite pas le quartier, j''étais juste de passage pour rendre visite à ma sœur. Je peux vous donner le numéro de mon employeur si vous voulez vérifier.'),
 (21878,'On m''a convoqué, mais je crois qu''il y a erreur sur la personne. Ma femme était avec moi, elle vous dira la même chose. Je peux vous donner le numéro de mon employeur si vous voulez vérifier. Si ça me revient, je vous appelle.'),
 (21189,'On m''a dit que quelqu''un du quartier avait « tout vu », mais quand je lui ai demandé, il m''a répondu qu''il ne se souvenait plus de rien. C''est un quartier tranquille d''habitude, ça nous a tous secoués. Vous devriez interroger les gens de l''immeuble d''en face, ils voient tout.'),
 (28826,'Tout m''a semblé parfaitement normal. Ne comptez pas sur moi pour témoigner au tribunal.'),
